// Pinned MessageBoxClient and SDK Git sources, real loopback HTTP. Socket.IO is unavailable.
import {spawn} from 'node:child_process';
import {createInterface} from 'node:readline';
import {pathToFileURL} from 'node:url';
import {mkdtemp,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import assert from 'node:assert/strict';
const sdk=process.env.SDK_SOURCE_DIR;
const clientSource=process.env.CLIENT_SOURCE_DIR;
const {MessageBoxClient}=await import(pathToFileURL(`${clientSource}/packages/messaging/message-box-client/src/MessageBoxClient.ts`));
const {AuthFetch}=await import(pathToFileURL(`${sdk}/src/auth/clients/AuthFetch.ts`));
const {default:ProtoWallet}=await import(pathToFileURL(`${sdk}/src/wallet/ProtoWallet.ts`));
const {default:PrivateKey}=await import(pathToFileURL(`${sdk}/src/primitives/PrivateKey.ts`));
const dir=await mkdtemp(join(tmpdir(),'messagebox-client-fixture-'));
const child=spawn(process.env.AUTH_HTTP_FIXTURE,[],{stdio:['ignore','pipe','inherit'],env:{...process.env,AUTH_TEST_DB:join(dir,'auth.sqlite')}});
const exited=new Promise(resolve=>{child.once('error',error=>resolve({error}));child.once('exit',(code,signal)=>resolve({code,signal}));});
const lines=createInterface({input:child.stdout})[Symbol.asyncIterator]();
try {
 const ready=await Promise.race([lines.next(),exited.then(result=>({earlyExit:result}))]);
 assert.ok(!ready.earlyExit,`fixture exited before reporting its port: ${JSON.stringify(ready.earlyExit)}`);
 const port=Number(ready.value); assert.ok(port>0);
 const host=`http://127.0.0.1:${port}`, server=new PrivateKey(3).toPublicKey().toString();
 const wallet=new ProtoWallet(new PrivateKey(2));
 let paymentAttempted=false;
 wallet.createAction=async()=>{paymentAttempted=true;throw new Error('Payments are disabled in this test');};
 const client=new MessageBoxClient({host,walletClient:wallet,serverIdentityKeysByHost:{[host]:server}});
 const messages=await client.listMessagesLite({messageBox:'inbox'});
 assert.equal(messages.length,1); assert.equal(messages[0].messageId,'sdk-message-1');
 assert.equal(messages[0].sender,new PrivateKey(4).toPublicKey().toString());
 assert.equal(messages[0].body,'hello from test');
 const empty=await client.listMessagesLite({messageBox:'inbox',offset:1}); assert.deepEqual(empty,[]);
 const self=new PrivateKey(2).toPublicKey().toString();
 const sent=await client.sendMessage({recipient:self,messageBox:'inbox',body:'cycle payload \"quoted\"\nline',skipEncryption:true,checkPermissions:false},host);
 assert.equal(sent.status,'success'); assert.match(sent.messageId,/^[0-9a-f]{64}$/);
 const afterSend=await client.listMessagesLite({messageBox:'inbox'});
 assert.equal(afterSend.find(message=>message.messageId===sent.messageId)?.body,'cycle payload \"quoted\"\nline');
 const attackerWallet=new ProtoWallet(new PrivateKey(4));
 attackerWallet.createAction=async()=>{throw new Error('Payments are disabled in this test');};
 const attacker=new MessageBoxClient({host,walletClient:attackerWallet,serverIdentityKeysByHost:{[host]:server}});
 assert.deepEqual(await attacker.listMessagesLite({messageBox:'inbox'}),[]);
 const attackerAuth=new AuthFetch(attackerWallet,undefined,undefined,undefined,{responseTimeoutMs:3000});
 const denied=await attackerAuth.fetch(`${host}/acknowledgeMessage`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({messageIds:[sent.messageId]}),requireMutualAuth:true,expectedIdentityKey:server,allowPayments:false});
 assert.equal(denied.status,400); assert.equal((await denied.json()).code,'ERR_INVALID_ACKNOWLEDGMENT');
 await assert.rejects(attacker.acknowledgeMessage({messageIds:[sent.messageId],host}));
 assert.equal((await client.listMessagesLite({messageBox:'inbox'})).some(message=>message.messageId===sent.messageId),true);
 assert.equal(await client.acknowledgeMessage({messageIds:[sent.messageId],host}),'success');
 const afterAck=await client.listMessagesLite({messageBox:'inbox'});
 assert.equal(afterAck.some(message=>message.messageId===sent.messageId),false);
 const pageSent=await client.sendMessage({recipient:self,messageBox:'inbox',messageId:'page-id',body:'page test',skipEncryption:true,checkPermissions:false},host);
 assert.equal(pageSent.messageId,'page-id');
 await assert.rejects(client.listMessagesLite({messageBox:'inbox',pageSize:1,maxPages:1}),/pagination exceeded/i);
 const pages=await client.listMessagesLite({messageBox:'inbox',pageSize:1});
 assert.equal(pages.length,2);
 assert.deepEqual(new Set(pages.map(message=>message.messageId)),new Set(['sdk-message-1','page-id']));
 assert.equal((await client.listMessagesLite({messageBox:'inbox',limit:1})).length,1);
 assert.deepEqual((await client.listMessagesLite({messageBox:'inbox',messageId:'page-id'})).map(message=>message.messageId),['page-id']);
 assert.deepEqual(await client.listMessagesLite({messageBox:'inbox',messageId:'missing-id'}),[]);
 assert.deepEqual((await client.listMessagesLite({messageBox:'inbox',limit:1,messageId:'page-id'})).map(message=>message.messageId),['page-id']);
 assert.equal(await client.acknowledgeMessage({messageIds:['page-id'],host}),'success');
 const unicodeBox='通知📨',unicodeId='消息-📨',unicodeBody='你好，世界 🌍\n带引号：\"好\"\u2028\u2029';
 const unicodeSent=await client.sendMessage({recipient:self,messageBox:unicodeBox,messageId:unicodeId,body:unicodeBody,skipEncryption:true,checkPermissions:false},host);
 assert.equal(unicodeSent.messageId,unicodeId);
 assert.equal((await client.listMessagesLite({messageBox:unicodeBox})).find(message=>message.messageId===unicodeId)?.body,unicodeBody);
 assert.equal((await client.listMessagesLite({messageBox:unicodeBox,messageId:unicodeId}))[0]?.body,unicodeBody);
 assert.deepEqual(await attacker.listMessagesLite({messageBox:unicodeBox,messageId:unicodeId}),[]);
 assert.equal(await client.acknowledgeMessage({messageIds:[unicodeId],host}),'success');
 assert.deepEqual(await client.listMessagesLite({messageBox:unicodeBox}),[]);
 const recipient4=new PrivateKey(4).toPublicKey().toString(),secretText='端到端 secret 📬';
 const encryptedSent=await client.sendMessage({recipient:recipient4,messageBox:'inbox',body:secretText,checkPermissions:false},host);
 assert.match(encryptedSent.messageId,/^[0-9a-f]{64}$/);
 const encryptedRaw=await attackerAuth.fetch(`${host}/listMessages`,{method:'POST',headers:{'content-type':'application/json'},body:'{"messageBox":"inbox","offset":0}',requireMutualAuth:true,expectedIdentityKey:server,allowPayments:false});
 const encryptedRows=(await encryptedRaw.json()).messages;
 const stored=encryptedRows.find(message=>message.messageId===encryptedSent.messageId);
 assert.ok(stored);assert.match(stored.body,/encryptedMessage/);assert.equal(stored.body.includes(secretText),false);
 assert.equal((await attacker.listMessagesLite({messageBox:'inbox'})).find(message=>message.messageId===encryptedSent.messageId)?.body,secretText);
 assert.equal((await client.listMessagesLite({messageBox:'inbox'})).some(message=>message.messageId===encryptedSent.messageId),false);
 assert.equal(await attacker.acknowledgeMessage({messageIds:[encryptedSent.messageId],host}),'success');
 assert.deepEqual(await attacker.listMessagesLite({messageBox:'inbox'}),[]);
 await assert.rejects(client.sendMessage({recipient:self,messageBox:'paidbox',messageId:'paid-id',body:'not delivered',skipEncryption:true,checkPermissions:false},host),/HTTP 501/);
 assert.deepEqual(await client.listMessagesLite({messageBox:'paidbox'}),[]);
 const quote=await client.getMessageBoxQuote({recipient:self,messageBox:'paidbox'},host);
 assert.equal(quote.deliveryFee,7);assert.equal(quote.recipientFee,0);assert.equal(quote.deliveryAgentIdentityKey,server);
 const oneArrayQuote=await client.getMessageBoxQuote({recipient:[self],messageBox:'inbox'},host);
 assert.equal(oneArrayQuote.quotesByRecipient.length,1);assert.equal(oneArrayQuote.quotesByRecipient[0].recipient,self);
 const multiQuote=await client.getMessageBoxQuote({recipient:[self,recipient4],messageBox:'inbox'},host);
 assert.equal(multiQuote.quotesByRecipient.length,2);assert.equal(multiQuote.totals.totalForPayableRecipients,0);
 assert.deepEqual(new Set(multiQuote.quotesByRecipient.map(q=>q.recipient)),new Set([self,recipient4]));
 const paidMultiQuote=await client.getMessageBoxQuote({recipient:[self,recipient4],messageBox:'paidbox'},host);
 assert.equal(paidMultiQuote.totals.deliveryFees,14);assert.equal(paidMultiQuote.totals.totalForPayableRecipients,14);
 const encodedQuote=await client.getMessageBoxQuote({recipient:self,messageBox:'a b+c/中'},host);
 assert.equal(encodedQuote.deliveryFee,0);assert.equal(encodedQuote.recipientFee,0);

 const checked=await client.sendMessage({recipient:self,messageBox:'inbox',messageId:'checked-id',body:'free checked message',skipEncryption:true,checkPermissions:true},host);
 assert.equal(checked.messageId,'checked-id');
 assert.equal((await client.listMessagesLite({messageBox:'inbox',messageId:'checked-id'}))[0]?.body,'free checked message');
 assert.equal(await client.acknowledgeMessage({messageIds:['checked-id'],host}),'success');
 const batch=await client.sendMessageToRecipients({recipients:[self,recipient4],messageBox:'inbox',body:'batch hello 📦',skipEncryption:true},host);
 assert.equal(batch.status,'success');assert.equal(batch.sent.length,2);assert.deepEqual(new Set(batch.sent.map(entry=>entry.recipient)),new Set([self,recipient4]));
 const selfId=batch.sent.find(entry=>entry.recipient===self).messageId,otherId=batch.sent.find(entry=>entry.recipient===recipient4).messageId;
 assert.notEqual(selfId,otherId);
 assert.equal((await client.listMessagesLite({messageBox:'inbox',messageId:selfId}))[0]?.body,'batch hello 📦');
 assert.equal((await attacker.listMessagesLite({messageBox:'inbox',messageId:otherId}))[0]?.body,'batch hello 📦');
 assert.deepEqual(await attacker.listMessagesLite({messageBox:'inbox',messageId:selfId}),[]);
 assert.equal(await client.acknowledgeMessage({messageIds:[selfId],host}),'success');
 assert.equal(await attacker.acknowledgeMessage({messageIds:[otherId],host}),'success');
 assert.deepEqual(await client.listMessagesLite({messageBox:'inbox',messageId:selfId}),[]);
 assert.deepEqual(await attacker.listMessagesLite({messageBox:'inbox',messageId:otherId}),[]);
 const fakeToken='fake-device-token-123',deviceLabel='桌面📱';
 const registered=await client.registerDevice({fcmToken:fakeToken,deviceId:deviceLabel,platform:'ios'},host);
 assert.equal(registered.status,'success');assert.ok(registered.deviceId>0);
 const devices=await client.listRegisteredDevices(host);const device=devices.find(item=>item.deviceId===deviceLabel);
 assert.equal(device.fcmToken,`...${fakeToken.slice(-10)}`);assert.equal(device.platform,'ios');
 assert.equal((await attacker.listRegisteredDevices(host)).some(item=>item.deviceId===deviceLabel),false);
 await assert.rejects(attacker.registerDevice({fcmToken:fakeToken,deviceId:'other',platform:'web'},host),/HTTP 409/);
 const updated=await client.registerDevice({fcmToken:fakeToken,deviceId:'更新设备',platform:'android'},host);
 assert.equal(updated.deviceId,registered.deviceId);
 const updatedDevice=(await client.listRegisteredDevices(host)).find(item=>item.id===registered.deviceId);
 assert.equal(updatedDevice.deviceId,'更新设备');assert.equal(updatedDevice.platform,'android');
 const minimal=await client.registerDevice({fcmToken:'fake-no-optional'},host);assert.ok(minimal.deviceId>0);
 assert.ok((await client.listRegisteredDevices(host)).some(item=>item.id===minimal.deviceId));
 const devicePage0=await client.listRegisteredDevices(host,{limit:1,offset:0});
 const devicePage1=await client.listRegisteredDevices(host,{limit:1,offset:1});
 assert.equal(devicePage0.length,1);assert.equal(devicePage1.length,1);assert.notEqual(devicePage0[0].id,devicePage1[0].id);
 assert.deepEqual(await client.listRegisteredDevices(host,{limit:1,offset:100}),[]);
 assert.equal((await attacker.listRegisteredDevices(host,{limit:1,offset:0})).length,1);


 const permissionBox='权限测试📬';
 assert.equal(await client.getMessageBoxPermission({recipient:self,messageBox:permissionBox},host),null);
 await client.setMessageBoxPermission({messageBox:permissionBox,recipientFee:0},host);
 const boxPermission=await client.getMessageBoxPermission({recipient:self,messageBox:permissionBox},host);
 assert.equal(boxPermission.messageBox,permissionBox);assert.equal(boxPermission.recipientFee,0);assert.equal(boxPermission.sender,null);
 await client.setMessageBoxPermission({messageBox:permissionBox,recipientFee:-1,sender:recipient4},host);
 const scopedPermission=await client.getMessageBoxPermission({recipient:self,messageBox:permissionBox,sender:recipient4},host);
 assert.equal(scopedPermission.sender,recipient4);assert.equal(scopedPermission.recipientFee,-1);
 assert.equal(await attacker.getMessageBoxPermission({recipient:recipient4,messageBox:permissionBox},host),null);
 assert.equal(await attacker.getMessageBoxPermission({recipient:self,messageBox:permissionBox},host),null);
 await client.setMessageBoxPermission({messageBox:'fee-test',recipientFee:23},host);
 assert.equal((await client.getMessageBoxPermission({recipient:self,messageBox:'fee-test'},host)).recipientFee,23);
 assert.equal((await attacker.getMessageBoxQuote({recipient:self,messageBox:'fee-test'},host)).recipientFee,23);
 const allPermissions=await client.listMessageBoxPermissions(undefined,host);
 assert.ok(allPermissions.length>=3);
 const filteredPermissions=await client.listMessageBoxPermissions({messageBox:permissionBox},host);
 assert.equal(filteredPermissions.length,2);assert.deepEqual(new Set(filteredPermissions.map(p=>p.sender)),new Set([null,recipient4]));
 const permissionPage0=await client.listMessageBoxPermissions({messageBox:permissionBox,limit:1,offset:0},host);
 const permissionPage1=await client.listMessageBoxPermissions({messageBox:permissionBox,limit:1,offset:1},host);
 assert.equal(permissionPage0.length,1);assert.equal(permissionPage1.length,1);assert.notEqual(permissionPage0[0].sender,permissionPage1[0].sender);
 assert.deepEqual(await attacker.listMessageBoxPermissions({messageBox:permissionBox},host),[]);
 const blockedQuote=await attacker.getMessageBoxQuote({recipient:self,messageBox:permissionBox},host);
 assert.equal(blockedQuote.recipientFee,-1);
 await assert.rejects(attacker.sendMessage({recipient:self,messageBox:permissionBox,messageId:'blocked-test',body:'blocked',skipEncryption:true,checkPermissions:true},host),/blocked/i);
 assert.deepEqual(await client.listMessagesLite({messageBox:permissionBox,messageId:'blocked-test'}),[]);
 const wrong=new MessageBoxClient({host,walletClient:wallet,serverIdentityKeysByHost:{[host]:new PrivateKey(4).toPublicKey().toString()}});
 await assert.rejects(wrong.listMessagesLite({messageBox:'inbox'}),/identity does not match/i);
 assert.equal(paymentAttempted,false);
 console.log('Pinned Git-source MessageBoxClient send/list/ack: HTTP authenticated cycle, offset, and wrong identity rejection passed. Socket.IO unavailable and untested; payments disabled.');
} finally {if(child.pid && child.exitCode===null && child.signalCode===null)child.kill('SIGTERM');await exited;await rm(dir,{recursive:true,force:true});}
